tiles.setCurrentTilemap(tilemap`Map`)
game.splash("WASD: Movement")
game.splash("A: Bullets | B: Fireball")
let countDownMinutes = 2
info.startCountdown(countDownMinutes * 60)
isPlaying += 1
PlayerStart()
EnemyCreator(1)
game.onUpdate(function () {
    facingDot.y = playerCharacter.y
    if (xDirection == 1) {
        facingDot.left = playerCharacter.right
        facingDot.x += 1
    } else if (xDirection == -1) {
        facingDot.right = playerCharacter.left
        facingDot.x += -1
    } else if (yDirection == 1) {
        facingDot.top = playerCharacter.bottom
        facingDot.y += 1
    } else if (yDirection == -1) {
        facingDot.bottom = playerCharacter.top
        facingDot.y += -1
    }
    fireballDelayUI.sayText("Fireball:" + convertToText(fireballDelay))
    killsUI.sayText("Kills: " + convertToText(kills))
    if (controller.dx() == 0 && controller.dy() == 0) {
        animation.setAction(playerCharacter, ActionKind.Idle)
    } else {
        animation.setAction(playerCharacter, ActionKind.Walking)
    }
})
game.onUpdateInterval(5000, function () {
    EnemyCreator(1)
})
game.onUpdateInterval(2000, function () {
    if (sprites.allOfKind(SpriteKind.shooterEnemy).length > 0) {
        EnemyShooting(sprites.allOfKind(SpriteKind.shooterEnemy)._pickRandom(), playerCharacter)
        canFireFireball = true
    }
})
game.onUpdateInterval(1000, function () {
    if (fireballDelay > 0) {
        fireballDelay += -1
    }
})
